sp_AbrirCaixa	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_AbrirCaixa`(\n\n    IN p_idEmpresa INT,\n\n    IN p_idUsuario INT,\n\n    IN p_saldoInicial DECIMAL(10,2),\n\n    IN p_nomeOperador VARCHAR(120)\n\n)\nBEGIN\n\n    INSERT INTO Caixa (idEmpresa, usuario_open_id, dthOpen, saldoInicial, saldoDinheiro, fAtivo, nomeOperador)\n\n    VALUES (p_idEmpresa, p_idUsuario, CONVERT_TZ(NOW(), '+00:00', '-03:00'), p_saldoInicial, p_saldoInicial, 1, p_nomeOperador);\n\n    SELECT LAST_INSERT_ID() AS idCaixa;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
